L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "\228\184\128\230\151\165\228\184\173\228\184\128\231\183\146\227\129\171\233\129\138\227\130\147\227\129\167\227\130\130\227\128\129\230\172\161\227\129\174\230\151\165\227\129\171\227\129\170\227\130\139\227\129\168\227\129\191\227\130\147\227\129\170\231\167\129\227\129\174\227\129\147\227\129\168\227\129\171\230\176\151\227\129\165\227\129\132\227\129\166\227\129\143\227\130\140\227\129\170\227\129\132\227\128\130"
L16_1.m_Talk_JPN = L17_1
L17_1 = "One day I'd play with them all day, but the next day they wouldn't recognize me at all."
L16_1.m_Talk_ENG = L17_1
L17_1 = "\229\147\170\230\128\149\228\184\128\232\181\183\231\142\169\228\186\134\228\184\128\229\164\169\239\188\140\229\136\176\228\186\134\231\172\172\228\186\140\229\164\169\229\164\167\229\174\182\233\131\189\230\156\131\228\184\141\232\170\141\232\173\152\230\136\145\227\128\130"
L16_1.m_Talk_TWN = L17_1
L17_1 = "\224\184\167\224\184\177\224\184\153\224\184\171\224\184\153\224\184\182\224\185\136\224\184\135\224\184\137\224\184\177\224\184\153\224\185\128\224\184\165\224\185\136\224\184\153\224\184\129\224\184\177\224\184\154\224\184\158\224\184\167\224\184\129\224\185\128\224\184\130\224\184\178\224\184\151\224\184\177\224\185\137\224\184\135\224\184\167\224\184\177\224\184\153 \224\185\129\224\184\149\224\185\136\224\184\167\224\184\177\224\184\153\224\184\149\224\185\136\224\184\173\224\184\161\224\184\178\224\184\158\224\184\167\224\184\129\224\185\128\224\184\130\224\184\178\224\184\129\224\185\135\224\184\136\224\184\179\224\184\137\224\184\177\224\184\153\224\185\132\224\184\161\224\185\136\224\185\132\224\184\148\224\185\137\224\185\128\224\184\165\224\184\162\224\185\129\224\184\165\224\185\137\224\184\167"
L16_1.m_Talk_THA = L17_1
L17_1 = "C\195\179 h\195\180m t\195\180i ch\198\161i v\225\187\155i h\225\187\141 c\225\186\163 ng\195\160y, nh\198\176ng ng\195\160y h\195\180m sau l\195\160 h\225\187\141 kh\195\180ng h\225\187\129 nh\225\186\173n ra t\195\180i n\225\187\175a."
L16_1.m_Talk_VTN = L17_1
L17_1 = "\229\147\170\230\128\149\228\184\128\232\181\183\231\142\169\228\186\134\228\184\128\229\164\169\239\188\140\229\136\176\228\186\134\231\172\172\228\186\140\229\164\169\229\164\167\229\174\182\233\131\189\228\188\154\228\184\141\232\174\164\232\175\134\230\136\145\227\128\130"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich kann den ganzen Tag mit ihnen spielen. Am n\195\164chsten Tag erkennen sie mich nicht wieder."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Un jour, je peux jouer avec eux du matin au soir, mais le lendemain, ils ne me reconnaissent m\195\170me plus."
